<script setup lang="ts">
import { computed, onBeforeUnmount, reactive, ref, watch } from 'vue'
import AppIcon from '../components/AppIcon.vue'
import DentalCanvas from './DentalCanvas.vue'
import DentalCoach from './DentalCoach.vue'
import DentalPhotoSimulator from './DentalPhotoSimulator.vue'
import DentalLocalLearning from './DentalLocalLearning.vue'
import DentalScreening from './DentalScreening.vue'
import { chartRows, toothLabel, type Appliance, type DentalView } from './model'
import { blankEdit, caseVersion, categories, downloadCase, modelledCases, orthodonticCases, orthodonticSources, photoSignature, photoViews, researchPartition, validCaseId, type CasePhoto, type DentalSimulation } from './caseModel'
import './caseStudio.css'
const props = defineProps<{ reducedMotion: boolean; user: { id: number; email: string } | null; authPending: boolean; authError: string }>()
const emit = defineEmits<{ authenticate: [email: string, password: string, register: boolean] }>()
const tab = ref<'workspace'|'library'|'practice'|'screening'>('workspace'), audience = ref('Dental student'), screeningKey=ref(0)
const caseId = ref('crowding'), subject = ref('CASE_001'), notes = ref(''), findings = ref<string[]>([]), reviewer = ref(''), reviewed = ref(false)
const search = ref(''), category = ref('all'), selected = ref(11), view = ref<DentalView>('front'), appliance = ref<Appliance>('none')
const simulation = reactive<DentalSimulation>({ caseId: 'crowding', intensity: .75, alignment: 0, edits: {} })
const photos = ref<CasePhoto[]>([]), activePhotoId = ref(''), photoBusy = ref(false), photoError = ref(''), notice = ref(''), canvasError = ref(''), canvasKey = ref(0)
const markerMode = ref(false), markerNote = ref(''), markerX = ref(50), markerY = ref(50)
const canvas = ref<InstanceType<typeof DentalCanvas>>()
const photoExercise = ref<{photoId:string;labels:string[];choices:string[];submitted:boolean;matches:boolean}|null>(null)
const exercisePhoto = computed(()=>photos.value.find(photo=>photo.id===photoExercise.value?.photoId))
const current = computed(() => orthodonticCases.find(item => item.id === caseId.value) || orthodonticCases[0]!)
const activePhoto = computed(() => photos.value.find(photo => photo.id === activePhotoId.value))
const sources = computed(() => orthodonticSources.filter(source => current.value.source_ids.includes(source.id)))
const filtered = computed(() => orthodonticCases.filter(item => (category.value==='all'||item.category===category.value) && [item.name,item.summary,...item.recognition].join(' ').toLowerCase().includes(search.value.toLowerCase().trim())))
const edit = computed(() => simulation.edits[selected.value] ??= blankEdit())
let photoGeneration = 0
watch(caseId, value => { simulation.caseId=value; simulation.alignment=0; simulation.edits={}; canvasError.value=''; reviewed.value=false })
watch([subject, notes, findings, photos, reviewer], () => { reviewed.value=false }, { deep:true })
function openCase(id: string) { caseId.value=id; tab.value='workspace'; view.value='front'; notice.value='' }
function openScreeningSimulator(hash:string){const photo=photos.value.find(item=>item.sha256===hash);if(photo){activePhotoId.value=photo.id;tab.value='workspace'}}
function resetModel() { simulation.alignment=0; simulation.intensity=.75; simulation.edits={}; canvas.value?.reset() }
function clearPhotos() { photoGeneration++; for (const photo of photos.value) URL.revokeObjectURL(photo.url); photos.value=[]; activePhotoId.value=''; photoBusy.value=false }
function newCase() { clearPhotos(); screeningKey.value++; photoExercise.value=null; subject.value='CASE_001'; notes.value=''; findings.value=[]; reviewer.value=''; reviewed.value=false; resetModel(); notice.value='New case started. Previous photos and notes were cleared from memory.' }
onBeforeUnmount(clearPhotos)
async function importPhotos(event: Event) {
  const input=event.target as HTMLInputElement, files=Array.from(input.files||[]); input.value=''; if(!files.length)return
  photoError.value=''; notice.value=''
  if(files.length+photos.value.length>6){photoError.value='Keep up to six photos per case. Remove a photo before adding another.';return}
  const version=++photoGeneration; photoBusy.value=true; const prepared:CasePhoto[]=[]
  try {
    for(const file of files){
      if(file.size>10000000||file.size===0)throw new Error('Each photo must be between 1 byte and 10 MB.')
      const bytes=await file.arrayBuffer(); const mime=photoSignature(new Uint8Array(bytes))
      const digest=await crypto.subtle.digest('SHA-256',bytes), hash=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('')
      if(photos.value.some(photo=>photo.sha256===hash)||prepared.some(photo=>photo.sha256===hash))throw new Error('That photo is already attached to this case.')
      if(version!==photoGeneration)return
      const url=URL.createObjectURL(new Blob([bytes],{type:mime})), image=new Image(); image.src=url
      try { await image.decode(); if(!image.naturalWidth||image.naturalWidth*image.naturalHeight>24000000)throw new Error('Choose a photo with no more than 24 million pixels.') }
      catch(failure){URL.revokeObjectURL(url);throw failure instanceof Error?failure:new Error('This photo could not be decoded.')}
      prepared.push({id:crypto.randomUUID(),url,view:photoViews[Math.min(photos.value.length+prepared.length,5)]!,width:image.naturalWidth,height:image.naturalHeight,sha256:hash,markers:[]})
    }
    if(version!==photoGeneration)return
    photos.value.push(...prepared);activePhotoId.value=prepared[0]!.id;notice.value=`${prepared.length} photo${prepared.length===1?'':'s'} added locally. Nothing was sent to AI.`
  } catch(failure){if(version===photoGeneration)photoError.value=failure instanceof Error?failure.message:'The photos could not be opened.'}
  finally {if(version!==photoGeneration||!prepared.every(photo=>photos.value.includes(photo)))for(const photo of prepared)URL.revokeObjectURL(photo.url);if(version===photoGeneration)photoBusy.value=false}
}
function removePhoto(id: string) { const photo=photos.value.find(item=>item.id===id);if(photo)URL.revokeObjectURL(photo.url);photos.value=photos.value.filter(item=>item.id!==id);if(activePhotoId.value===id)activePhotoId.value=photos.value[0]?.id||'' }
function addMarker(x=markerX.value,y=markerY.value) { if(!activePhoto.value||!Number.isFinite(x)||!Number.isFinite(y)||x<0||x>100||y<0||y>100)return; if(activePhoto.value.markers.length>=32){photoError.value='Use up to 32 markers per photo.';return};activePhoto.value.markers.push({x,y,tooth:selected.value,note:markerNote.value.trim().slice(0,120)});markerX.value=x;markerY.value=y }
function photoClick(event:MouseEvent) {if(!markerMode.value)return;const bounds=(event.currentTarget as SVGElement).getBoundingClientRect();addMarker((event.clientX-bounds.left)/bounds.width*100,(event.clientY-bounds.top)/bounds.height*100)}
function exportRecord(labelOnly=false){
  if(!validCaseId(subject.value)){photoError.value='Use a coded case ID: 1–48 letters, numbers, underscores or hyphens.';return}
  if(labelOnly&&(!reviewed.value||!reviewer.value.trim()||!photos.value.length||!findings.value.length))return
  photoError.value=''
  const record={schema_version:'humantwin-dental-case-v1',library_version:caseVersion,subject_id:subject.value,created_at:new Date().toISOString(),use:'education-research',clinical_validation:false,model_training_performed:false,review:{status:reviewed.value?'self-attested-review':'unreviewed',reviewer_code:reviewer.value||null},reported_findings:findings.value,clinician_notes:notes.value,photos:photos.value.map(({view,width,height,sha256,markers,study})=>({view,width,height,sha256,markers,photo_study:study??null})),image_bytes_included:false,reference_case_id:caseId.value,illustrative_model:JSON.parse(JSON.stringify(simulation)),sources:sources.value.map(s=>s.url),...(labelOnly?{proposed_patient_group_partition:researchPartition(subject.value),requires_dataset_rights_and_independent_review:true}:{})}
  downloadCase(record,labelOnly?'humantwin-reviewed-dental-label.jsonl':'humantwin-dental-case.json',labelOnly);notice.value=labelOnly?'Research label exported with photo fingerprints. This does not train or validate a model.':'Case notes exported. Photos remain local; image files are not included.'
}

const exam = ref<number[]>([]), examIndex = ref(0), answer = ref<number|null>(null), submitted = ref(false), results = ref<{id:string;correct:boolean}[]>([]), examDone = ref(false)
const examCase = computed(() => orthodonticCases[exam.value[examIndex.value]??0]!)
const examSimulation = computed<DentalSimulation>(()=>({caseId:examCase.value.id,intensity:.8,alignment:0,edits:{}}))
function startExam(){const pool=orthodonticCases.map((_,i)=>i);for(let i=pool.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j]!,pool[i]!]};exam.value=pool.slice(0,10);examIndex.value=0;answer.value=null;submitted.value=false;results.value=[];examDone.value=false;tab.value='practice'}
function checkAnswer(){if(answer.value===null||submitted.value)return;results.value.push({id:examCase.value.id,correct:answer.value===examCase.value.quiz.answer_index});submitted.value=true}
function nextQuestion(){if(!submitted.value)return;if(examIndex.value+1===exam.value.length){examDone.value=true;return};examIndex.value++;answer.value=null;submitted.value=false}
function startPhotoExercise(){if(!reviewed.value||!activePhoto.value||!findings.value.length)return;photoExercise.value={photoId:activePhoto.value.id,labels:[...findings.value],choices:[],submitted:false,matches:false};tab.value='practice'}
function checkPhotoExercise(){if(!photoExercise.value||photoExercise.value.submitted||!photoExercise.value.choices.length)return;const question=photoExercise.value;question.matches=[...question.labels].sort().join('|')===[...question.choices].sort().join('|');question.submitted=true}
</script>
<template>
 <section class="ortho-studio" aria-label="Patient cases and orthodontic practice" data-testid="ortho-studio">
  <div class="ortho-hero"><div><span class="dental-eyebrow">THE DENTAL CASE ROOM</span><h2>Every smile has<br/>something to teach.</h2><p>Bring a photo. Explore the bite. Build your clinical reasoning.</p><div class="ortho-hero-tags"><span><i/>Photos stay on this device</span><span>Evidence-linked learning</span></div></div><div class="ortho-hero-stat"><strong>{{orthodonticCases.length}}<span>+</span></strong><p>orthodontic topics</p><small>One place to observe, explore & practise.</small><div class="ortho-mini-arch" aria-hidden="true"><i v-for="n in 12" :key="n" :style="{'--tooth':n}"/></div></div></div>
  <div class="ortho-navigation"><div role="group" aria-label="Case room mode"><button :aria-pressed="tab==='workspace'" @click="tab='workspace'"><span>01</span>Case workspace</button><button :aria-pressed="tab==='library'" @click="tab='library'"><span>02</span>Condition library <small>{{orthodonticCases.length}}</small></button><button :aria-pressed="tab==='practice'" @click="tab='practice'"><span>03</span>Student practice</button><button :aria-pressed="tab==='screening'" @click="tab='screening'"><span>04</span>Orthodontic screening <small>41</small></button></div><label>Viewing as<select v-model="audience" aria-label="Case room audience"><option>Dental student</option><option>Dentist</option><option>Patient</option></select></label></div>
  <p v-if="notice" class="ortho-notice" role="status">{{notice}}</p><p v-if="photoError" class="dental-error" role="alert">{{photoError}}</p>
  <template v-if="tab==='workspace'">
   <div class="ortho-case-bar"><label class="ortho-subject">CASE ID<input v-model="subject" maxlength="48" pattern="[A-Za-z0-9_-]{1,48}" aria-label="Coded dental case ID"/></label><span class="ortho-case-status"><i/>{{photos.length?'Local case in progress':'Start with a photo or teaching example'}}</span><button class="button-secondary" @click="newCase">Clear case</button><button class="button-primary" @click="exportRecord()"><AppIcon name="download" :size="15"/>Export case</button></div>
   <div class="ortho-workspace-grid"><div class="ortho-main-column">
    <section class="ortho-photo-card panel"><div class="ortho-card-top"><div><span class="dental-eyebrow">01 / OBSERVE</span><h3>Patient photographs</h3></div><label class="button-secondary dental-file-button"><AppIcon name="plus" :size="15"/>{{photoBusy?'Opening…':'Add photos'}}<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="photoBusy||photos.length>=6" aria-label="Add patient dental photos" @change="importPhotos"/></label></div>
     <div v-if="!photos.length" class="ortho-photo-empty"><div class="ortho-photo-icon"><AppIcon name="tooth" :size="37"/><span>+</span></div><h4>Start with the patient’s smile.</h4><p>Add de-identified frontal, side and arch photographs.<br/>JPEG, PNG or WebP · up to 6 photos · 10 MB each</p><label class="button-primary dental-file-button">Choose photographs<input type="file" accept="image/jpeg,image/png,image/webp" multiple :disabled="photoBusy" aria-label="Choose patient photographs" @change="importPhotos"/></label><small>Use images you have permission to review. Photos stay in this session.</small></div>
     <template v-else-if="activePhoto"><div class="ortho-photo-strip" aria-label="Case photographs"><button v-for="photo in photos" :key="photo.id" :aria-pressed="activePhotoId===photo.id" :aria-label="`View ${photo.view} photograph`" @click="activePhotoId=photo.id"><img :src="photo.url" :alt="photo.view"/><span>{{photo.view}}</span></button></div><div class="ortho-photo-stage" :style="{aspectRatio:`${activePhoto.width}/${activePhoto.height}`}"><img :src="activePhoto.url" :alt="`Locally attached ${activePhoto.view.toLowerCase()} dental photograph`"/><svg viewBox="0 0 100 100" preserveAspectRatio="none" :class="{'is-marking':markerMode}" aria-label="Photo annotation overlay" @click="photoClick"><g v-for="(marker,i) in activePhoto.markers" :key="i"><circle :cx="marker.x" :cy="marker.y" r="1.3"/><text :x="marker.x+1.8" :y="marker.y-1">{{marker.tooth}}</text></g></svg></div><div class="ortho-photo-tools"><label>Photo view<select v-model="activePhoto.view" aria-label="Selected photograph view"><option v-for="name in photoViews" :key="name">{{name}}</option></select></label><button class="button-secondary" :aria-pressed="markerMode" @click="markerMode=!markerMode">{{markerMode?'Marking on':'Mark a tooth'}}</button><button class="dental-text-button ortho-delete" @click="removePhoto(activePhoto.id)">Remove photo</button></div><div v-if="markerMode" class="ortho-marker-tools"><p>Select a tooth in the chart, then click its location in the photo. Markers are manual observations.</p><div><label>X (%)<input v-model.number="markerX" type="number" min="0" max="100" aria-label="Photo marker X percent"/></label><label>Y (%)<input v-model.number="markerY" type="number" min="0" max="100" aria-label="Photo marker Y percent"/></label><label class="ortho-marker-note">Note<input v-model="markerNote" maxlength="120" placeholder="Visible feature to review" aria-label="Photo marker note"/></label><button class="button-secondary" @click="addMarker()">Add marker</button></div><ul><li v-for="(marker,i) in activePhoto.markers" :key="i">FDI {{marker.tooth}} · {{marker.note||'Manual point'}}<button :aria-label="`Remove photo marker ${i+1}`" @click="activePhoto.markers.splice(i,1)">×</button></li></ul></div></template>
     <div class="ortho-privacy-line"><AppIcon name="shield" :size="14"/>Nothing uploads automatically. Reloading clears photos and notes.</div>
    </section>
    <DentalPhotoSimulator v-if="activePhoto" :photo="activePhoto" :findings="findings" :user="user" :auth-pending="authPending" :auth-error="authError" @authenticate="(email,password,register)=>emit('authenticate',email,password,register)"/>
    <DentalLocalLearning v-else class="panel" :user="user" :auth-pending="authPending" :auth-error="authError" @authenticate="(email,password,register)=>emit('authenticate',email,password,register)"/>
    <section class="ortho-twin-card panel"><div class="ortho-card-top"><div><span class="dental-eyebrow">02 / EXPLORE · GENERIC REFERENCE</span><h3>{{activePhoto?'Separate teaching atlas':'The teaching twin'}}</h3></div><span class="ortho-reference-pill">Illustrative model</span></div><div class="ortho-preset-row"><label>Example<select v-model="caseId" aria-label="Orthodontic teaching example"><option v-for="item in orthodonticCases" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>Appliance<select v-model="appliance" aria-label="Case teaching appliance"><option value="none">No appliance</option><option value="metal">Metal braces</option><option value="ceramic">Ceramic braces</option></select></label></div><p v-if="!modelledCases.has(caseId)" class="ortho-soft-note">This topic uses a reference arch. {{current.name}} requires records beyond this model; read the case notes.</p>
     <div class="dental-views" role="group" aria-label="Case model view"><button v-for="angle in (['front','side','upper','lower'] as const)" :key="angle" :aria-pressed="view===angle" @click="view=angle">{{({front:'Front',side:'Side',upper:'Upper arch',lower:'Lower arch'})[angle]}}</button></div><div class="ortho-model-stage"><DentalCanvas :key="canvasKey" ref="canvas" :view="view" :selected="selected" :appliance="appliance" elastic="#399d91" :opening=".02" :reduced-motion="reducedMotion" :scan="null" :simulation="simulation" @select="selected=$event" @error="canvasError=$event"/><div class="ortho-model-caption"><span>{{current.name}}</span><small>FDI {{selected}} · {{toothLabel(selected).split(' · ').slice(1).join(' · ')}}</small></div><div v-if="canvasError" class="dental-canvas-error" role="alert"><p>{{canvasError}}</p><button class="button-secondary" @click="canvasKey++;canvasError=''">Retry case model</button></div></div>
     <div class="ortho-model-controls"><label>Example intensity<input v-model.number="simulation.intensity" type="range" min="0" max="1" step=".05" aria-label="Teaching example intensity"/></label><label>Illustrative alignment <output>{{Math.round(simulation.alignment*100)}}%</output><input v-model.number="simulation.alignment" type="range" min="0" max="1" step=".05" aria-label="Illustrative alignment preview"/><small>Explore a visual endpoint. This is not a treatment forecast or timeline.</small></label></div>
     <div class="ortho-tooth-chart" aria-label="Case tooth selection"><div v-for="(row,i) in chartRows" :key="i"><span>{{i===0?'UPPER':'LOWER'}}</span><button v-for="id in row" :key="id" :aria-pressed="selected===id" :aria-label="`Edit ${toothLabel(id)}`" @click="selected=id">{{id}}</button></div></div><details class="ortho-tooth-edits"><summary>Explore individual tooth position · FDI {{selected}}</summary><p>Offsets change the educational model only. Roots, bone and safe movement limits are not evaluated.</p><div><label>Sideways<input v-model.number="edit.x" type="range" min="-.35" max=".35" step=".01" aria-label="Selected tooth sideways offset"/></label><label>Up / down<input v-model.number="edit.y" type="range" min="-.25" max=".25" step=".01" aria-label="Selected tooth vertical offset"/></label><label>Forward / back<input v-model.number="edit.z" type="range" min="-.35" max=".35" step=".01" aria-label="Selected tooth depth offset"/></label><label>Rotation<input v-model.number="edit.rotation" type="range" min="-60" max="60" step="1" aria-label="Selected tooth rotation"/></label></div></details><div class="ortho-model-bottom"><span>Drag to rotate · scroll to zoom</span><button class="dental-text-button" @click="resetModel">Reset model</button></div><p class="ortho-model-boundary">The photo and reference twin are separate. Photo upload does not create a patient-specific 3D scan.</p>
    </section>
   </div><aside class="ortho-aside">
    <section class="ortho-case-note panel"><span class="dental-eyebrow">CASE IN FOCUS</span><span class="ortho-category">{{current.category}}</span><h3>{{current.name}}</h3><p>{{current.summary}}</p><h4>What to observe</h4><ul><li v-for="point in current.recognition" :key="point">{{point}}</li></ul><h4>{{audience==='Patient'?'Questions for your dental team':'What a clinician reviews'}}</h4><ul><li v-for="point in current.review" :key="point">{{point}}</li></ul><p class="ortho-soft-note">{{current.limits}}</p><div class="ortho-source-list"><a v-for="source in sources" :key="source.id" :href="source.url" target="_blank" rel="noopener noreferrer">{{source.publisher}} · {{source.title}} ↗</a></div></section>
    <section class="ortho-notebook panel"><span class="dental-eyebrow">03 / RECORD & REVIEW</span><h3>Case notebook</h3><p>Record your observations. Choosing a label does not confirm a diagnosis.</p><details><summary>Record discussion topics <span>{{findings.length}} selected</span></summary><div class="ortho-findings"><label v-for="item in orthodonticCases" :key="item.id"><input v-model="findings" type="checkbox" :value="item.id"/>{{item.name}}</label></div></details><label class="dental-field">{{audience==='Patient'?'What would you like to ask your dentist?':'Observations & provisional discussion notes'}}<textarea v-model="notes" rows="5" maxlength="2000" placeholder="Describe what is visible, what is unknown, and which records are needed." aria-label="Dental case notes"/></label><label class="dental-field">Reviewer code<input v-model="reviewer" maxlength="48" placeholder="e.g. REVIEWER_01" aria-label="Dental reviewer code"/></label><label class="dental-check"><input v-model="reviewed" type="checkbox" :disabled="!reviewer.trim()||!findings.length||!photos.length"/>I have reviewed the photo labels and have permission to export them for research. This is a self-reported review.</label><button class="button-secondary" :disabled="!reviewed||!validCaseId(subject)" @click="exportRecord(true)">Export reviewed research label</button><button class="button-secondary ortho-photo-exercise-launch" :disabled="!reviewed||!activePhoto" @click="startPhotoExercise">Practise with this reviewed photo</button><small>Exports labels, notes and photo fingerprints. Images are excluded. No model is trained automatically.</small></section>
    <DentalCoach :case-id="caseId" :findings="findings" :notes="notes" :photo="activePhoto" :user="user" :auth-pending="authPending" :auth-error="authError" @authenticate="(email,password,register)=>emit('authenticate',email,password,register)" @open="openCase"/>
   </aside></div>
  </template>
  <section v-else-if="tab==='library'" class="ortho-library" aria-label="Orthodontic condition library"><div class="ortho-library-heading"><div><span class="dental-eyebrow">LOOK CLOSER. THINK WIDER.</span><h3>A library of bite & alignment patterns.</h3><p>Learn the visible features, the missing information, and the questions that matter.</p></div><label class="ortho-search-label">Search topics<input v-model="search" type="search" placeholder="Crowding, open bite, impacted canine…" aria-label="Search orthodontic conditions"/></label></div><div class="ortho-filter-row" aria-label="Orthodontic topic categories"><button v-for="group in categories" :key="group" :aria-pressed="category===group" @click="category=group">{{group==='all'?'All topics':group}}</button></div><p v-if="!filtered.length" class="ortho-soft-note" role="status">No matching topics. Try another term or choose All topics.</p><div class="ortho-library-grid"><article v-for="(item,i) in filtered" :key="item.id" :data-case="item.id"><div class="ortho-library-visual" :class="item.category" aria-hidden="true"><span>{{String(i+1).padStart(2,'0')}}</span><div class="ortho-tooth-glyph" :class="item.id"><i v-for="n in 7" :key="n" :style="{'--n':n}"/></div><small>{{modelledCases.has(item.id)?'Interactive example':'Clinical vignette'}}</small></div><div class="ortho-library-copy"><span class="ortho-category">{{item.category}}</span><h4>{{item.name}}</h4><p>{{item.summary}}</p><button class="dental-text-button" @click="openCase(item.id)">Explore case <AppIcon name="arrowRight" :size="15"/></button></div></article></div><p class="ortho-library-footnote">Draft educational content linked to professional references. These topics overlap; an individual can have several findings. This is not a diagnostic classification of an uploaded photo.</p></section>
  <section v-else-if="tab==='practice'" class="ortho-practice panel" aria-label="Orthodontic student practice">
   <div v-if="photoExercise&&exercisePhoto" class="ortho-patient-exercise"><div class="ortho-exam-top"><span class="dental-eyebrow">PRACTISE WITH A REVIEWED PHOTO</span><button class="dental-text-button" @click="photoExercise=null">Return to topic tests</button></div><div class="ortho-exam-body"><div class="ortho-exercise-photo"><img :src="exercisePhoto.url" alt="Local dental case for a reviewer-labeled exercise"/><p>{{exercisePhoto.view}} · local photo · labels hidden until submission</p></div><div class="ortho-exam-question"><h3>Which discussion topics did the reviewer record for this case?</h3><p class="ortho-soft-note">Select all that apply. Compare your choices with self-attested case labels. Additional views or clinical records may be needed; this is not a diagnosis.</p><fieldset class="ortho-photo-answers" :disabled="photoExercise.submitted"><legend>Choose one or more topics</legend><label v-for="item in orthodonticCases" :key="item.id"><input v-model="photoExercise.choices" type="checkbox" :value="item.id"/>{{item.name}}</label></fieldset><button v-if="!photoExercise.submitted" class="button-primary" :disabled="!photoExercise.choices.length" @click="checkPhotoExercise">Compare with reviewer</button><div v-else class="ortho-explanation" aria-live="polite"><h4>{{photoExercise.matches?'Your choices match the reviewer labels.':'Compare the labels and discuss the differences.'}}</h4><p>The reviewer selected: {{orthodonticCases.filter(item=>photoExercise!.labels.includes(item.id)).map(item=>item.name).join('; ')}}.</p><p>Reviewer labels can be incomplete or incorrect. Resolve disagreements with the supervising dentist and complete clinical records.</p><button class="button-secondary" @click="photoExercise=null;tab='workspace'">Back to this case</button></div></div></div></div>
   <div v-else-if="!exam.length" class="ortho-exam-start"><span class="dental-eyebrow">TURN OBSERVATION INTO UNDERSTANDING</span><h3>Your next case starts here.</h3><p>Ten randomized questions across {{orthodonticCases.length}} topics. Review the reasoning and sources after each answer.</p><div><span>10 questions</span><span>Untimed</span><span>Explanation after every answer</span></div><button class="button-primary" @click="startExam">Start 10-question test</button><small>Educational self-assessment. Scores do not demonstrate clinical competence.</small><p class="ortho-own-photo-prompt">To practise on a patient photograph, attach it in the case workspace and have the labels reviewed first.</p></div>
   <div v-else-if="examDone" class="ortho-exam-results"><span class="dental-eyebrow">PRACTICE COMPLETE</span><h3>{{results.filter(item=>item.correct).length}}<span> / {{exam.length}}</span></h3><p>Keep the reasoning. Revisit the uncertain cases.</p><div><article v-for="item in results" :key="item.id"><span :class="{correct:item.correct}">{{item.correct?'✓':'↻'}}</span><button class="dental-text-button" @click="openCase(item.id)">{{orthodonticCases.find(c=>c.id===item.id)?.name}}</button><small>{{item.correct?'Correct':'Review suggested'}}</small></article></div><button class="button-primary" @click="startExam">Try another test</button><button class="button-secondary" @click="downloadCase({schema_version:'humantwin-dental-exam-v1',library_version:caseVersion,questions:results,score:results.filter(r=>r.correct).length,total:exam.length,clinical_competence_assessed:false},'humantwin-dental-practice.json')">Export practice result</button></div>
   <template v-else><div class="ortho-exam-top"><span class="dental-eyebrow">CASE {{String(examIndex+1).padStart(2,'0')}} / {{exam.length}}</span><span>{{results.filter(item=>item.correct).length}} correct so far</span><button class="dental-text-button" @click="startExam">Restart test</button></div><div class="ortho-exam-progress"><i :style="{width:`${examIndex/exam.length*100}%`}"/></div><div class="ortho-exam-body"><div><div v-if="modelledCases.has(examCase.id)" class="ortho-exam-model"><DentalCanvas :key="examIndex" view="front" :selected="11" appliance="none" elastic="#399d91" :opening=".02" :reduced-motion="reducedMotion" :scan="null" :simulation="examSimulation" @error="canvasError=$event"/><span>Teaching geometry · observe, then reason</span></div><div v-else class="ortho-vignette"><span class="dental-eyebrow">CLINICAL VIGNETTE</span><h4>Consider these observations.</h4><ul><li v-for="point in examCase.recognition" :key="point">{{point}}</li></ul><p>Additional clinical records are still required.</p></div></div><div class="ortho-exam-question"><span class="ortho-category">{{examCase.category}}</span><h3>{{examCase.quiz.question}}</h3><fieldset :disabled="submitted"><legend>Choose one answer</legend><label v-for="(option,i) in examCase.quiz.options" :key="i" :class="{'chosen':answer===i,'is-correct':submitted&&i===examCase.quiz.answer_index,'is-incorrect':submitted&&answer===i&&i!==examCase.quiz.answer_index}"><input v-model="answer" type="radio" name="ortho-answer" :value="i"/><span>{{String.fromCharCode(65+i)}}</span>{{option}}</label></fieldset><button v-if="!submitted" class="button-primary" :disabled="answer===null" @click="checkAnswer">Check answer</button><div v-else class="ortho-explanation" aria-live="polite"><h4>{{answer===examCase.quiz.answer_index?'Correct. Here’s the reasoning.':'A useful case to revisit.'}}</h4><p>{{examCase.quiz.explanation}}</p><a v-for="source in orthodonticSources.filter(s=>examCase.source_ids.includes(s.id)).slice(0,2)" :key="source.id" :href="source.url" target="_blank" rel="noopener noreferrer">{{source.publisher}} ↗ </a><button class="button-primary" @click="nextQuestion">{{examIndex+1===exam.length?'See results':'Next question'}} →</button></div></div></div></template>
  </section>
  <DentalScreening :key="screeningKey" v-show="tab==='screening'" :photos="photos" :subject="subject" :photo-busy="photoBusy" :user="user" :auth-pending="authPending" :auth-error="authError" @add-photos="importPhotos" @authenticate="(email,password,register)=>emit('authenticate',email,password,register)" @open-simulator="openScreeningSimulator"/>
 </section>
</template>
